  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision)
  }

  /** helper function to set the values of all input ports.
   * @param temperature payload for data port temperature
   * @param validity payload for data port validity
   * @param upper_limit payload for data port upper_limit
   */
  def put_concrete_inputs(temperature : Dual_Zone_Greenhouse.Temperature_Celsius,
                          validity : Dual_Zone_Greenhouse.Sensor_Validity.Type,
                          upper_limit : Dual_Zone_Greenhouse.Upper_Temperature_Limit): Unit = {
    put_temperature(temperature)
    put_validity(validity)
    put_upper_limit(upper_limit)
  }


  /** helper function to check Zone_B_Local_Decision_i_control_process_zone_b_local_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param eligibility method that will be called with the value of the outgoing data
   *        port 'eligibility'.
   * @param sensor_fault method that will be called with the value of the outgoing data
   *        port 'sensor_fault'.
   */
  def check_concrete_output(eligibility: Dual_Zone_Greenhouse.Ventilation_Eligibility.Type => B,
                            sensor_fault: Dual_Zone_Greenhouse.Sensor_Fault_Indication.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val eligibilityValue: Dual_Zone_Greenhouse.Ventilation_Eligibility.Type = get_eligibility().get
    if(!eligibility(eligibilityValue)) {
      testFailures = testFailures :+ st"'eligibility' did not match expected: value of the outgoing data port is ${eligibilityValue}"
    }
    val sensor_faultValue: Dual_Zone_Greenhouse.Sensor_Fault_Indication.Type = get_sensor_fault().get
    if(!sensor_fault(sensor_faultValue)) {
      testFailures = testFailures :+ st"'sensor_fault' did not match expected: value of the outgoing data port is ${sensor_faultValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_temperature(value : Dual_Zone_Greenhouse.Temperature_Celsius): Unit = {
    Art.insertInInfrastructurePort(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision.operational_api.temperature_Id, Dual_Zone_Greenhouse.Temperature_Celsius_Payload(value))
  }

  // setter for in DataPort
  def put_validity(value : Dual_Zone_Greenhouse.Sensor_Validity.Type): Unit = {
