  }

  // getter for out DataPort
  def get_eligibility(): Option[Dual_Zone_Greenhouse.Ventilation_Eligibility.Type] = {
    val value: Option[Dual_Zone_Greenhouse.Ventilation_Eligibility.Type] = get_eligibility_payload() match {
      case Some(Dual_Zone_Greenhouse.Ventilation_Eligibility_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port eligibility.  Expecting 'Dual_Zone_Greenhouse.Ventilation_Eligibility_Payload' but received ${v}")
      case _ => None[Dual_Zone_Greenhouse.Ventilation_Eligibility.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_eligibility_payload(): Option[Dual_Zone_Greenhouse.Ventilation_Eligibility_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision.initialization_api.eligibility_Id).asInstanceOf[Option[Dual_Zone_Greenhouse.Ventilation_Eligibility_Payload]]
  }

  // getter for out DataPort
  def get_sensor_fault(): Option[Dual_Zone_Greenhouse.Sensor_Fault_Indication.Type] = {
    val value: Option[Dual_Zone_Greenhouse.Sensor_Fault_Indication.Type] = get_sensor_fault_payload() match {
      case Some(Dual_Zone_Greenhouse.Sensor_Fault_Indication_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port sensor_fault.  Expecting 'Dual_Zone_Greenhouse.Sensor_Fault_Indication_Payload' but received ${v}")
      case _ => None[Dual_Zone_Greenhouse.Sensor_Fault_Indication.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_sensor_fault_payload(): Option[Dual_Zone_Greenhouse.Sensor_Fault_Indication_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_b_local_decision.initialization_api.sensor_fault_Id).asInstanceOf[Option[Dual_Zone_Greenhouse.Sensor_Fault_Indication_Payload]]
  }

